modelSource:
cube('analytics_mc26_ratio', {
    sql: "SELECT * FROM analytics_mc26_ratio WHERE channel = 'keep'",
    dimensions: { id: { sql: 'id', type: 'number', primary_key: true }, completed: { sql: 'completed', type: 'boolean' } },
    measures: {
      completed_count: { type: 'count', filters: [{ sql: `${CUBE}.completed = TRUE` }] },
      total_count: { type: 'count' },
      ratio: { type: 'number', sql: `CAST(${completed_count} AS DECIMAL(38,9)) / NULLIF(CAST(${total_count} AS DECIMAL(38,9)), CAST(0 AS DECIMAL(38,9)))` }
    }
  });
  cube('analytics_mc26_share', {
    sql: "SELECT * FROM analytics_mc26_share WHERE channel = 'keep'",
    dimensions: { id: { sql: 'id', type: 'number', primary_key: true }, region: { sql: 'region', type: 'string' } },
    measures: {
      value: { sql: 'amount', type: 'sum' },
      source_total: { sql: `${value}`, type: 'sum', multi_stage: true, group_by: [] },
      share: { type: 'number', multi_stage: true, sql: `CAST(${value} AS DECIMAL(38,9)) / NULLIF(CAST(${source_total} AS DECIMAL(38,9)), CAST(0 AS DECIMAL(38,9)))` }
    }
  });
  cube('analytics_mc26_calendar', {
    sql: "SELECT * FROM analytics_mc26_calendar WHERE channel = 'keep'",
    dimensions: { id: { sql: 'id', type: 'number', primary_key: true }, occurred_at: { sql: 'occurred_at', type: 'time' } },
    measures: {
      current: { sql: 'amount', type: 'sum' },
      prior: { sql: `${current}`, type: 'number', multi_stage: true, time_shift: [{ time_dimension: occurred_at, interval: '1 month', type: 'prior' }] },
      growth: { type: 'number', multi_stage: true, sql: `(CAST(${current} AS DECIMAL(38,9)) - CAST(${prior} AS DECIMAL(38,9))) / NULLIF(CAST(${prior} AS DECIMAL(38,9)), CAST(0 AS DECIMAL(38,9)))` }
    }
  });

setupSQL:
CREATE TABLE analytics_mc26_ratio(id integer PRIMARY KEY, completed boolean, channel text);
INSERT INTO analytics_mc26_ratio SELECT id, id <= 2, 'keep' FROM generate_series(1,10) AS input(id);
INSERT INTO analytics_mc26_ratio VALUES (11,TRUE,'exclude');
CREATE TABLE analytics_mc26_share(id integer PRIMARY KEY, region text, amount double precision, channel text);
INSERT INTO analytics_mc26_share VALUES (1,'A',50,'keep'),(2,'B',150,'keep'),(3,'C',999,'exclude');
CREATE TABLE analytics_mc26_calendar(id integer PRIMARY KEY, occurred_at timestamp, amount double precision, channel text);
